public class StatelessWebClientWebFluxServerIT {

    private static final JacksonMcpJsonMapper jsonMapper = new JacksonMcpJsonMapper(new ObjectMapper());

    private final ApplicationContextRunner serverContextRunner = new ApplicationContextRunner().withPropertyValues("spring.ai.mcp.server.protocol=STATELESS").withConfiguration(AutoConfigurations.of(McpServerStatelessAutoConfiguration.class, McpServerObjectMapperAutoConfiguration.class, StatelessToolCallbackConverterAutoConfiguration.class, McpServerStatelessWebFluxAutoConfiguration.class));

    private final ApplicationContextRunner clientApplicationContext = new ApplicationContextRunner().withConfiguration(AutoConfigurations.of(McpToolCallbackAutoConfiguration.class, McpClientAutoConfiguration.class, McpClientAnnotationScannerAutoConfiguration.class, StreamableHttpWebFluxTransportAutoConfiguration.class));

    @Test
    void clientServerCapabilities() {
        int serverPort = TestSocketUtils.findAvailableTcpPort();
        this.serverContextRunner.withUserConfiguration(TestMcpServerConfiguration.class).// @formatter:off
        withPropertyValues("spring.ai.mcp.server.streamable-http.mcp-endpoint=/mcp", "spring.ai.mcp.server.name=test-mcp-server", "spring.ai.mcp.server.streamable-http.keep-alive-interval=1s", // @formatter:on
        "spring.ai.mcp.server.version=1.0.0").run(serverContext -> {
            // Verify all required beans are present
            assertThat(serverContext).hasSingleBean(WebFluxStatelessServerTransport.class);
            assertThat(serverContext).hasSingleBean(RouterFunction.class);
            assertThat(serverContext).hasSingleBean(McpStatelessSyncServer.class);
            // Verify server properties are configured correctly
            McpServerProperties properties = serverContext.getBean(McpServerProperties.class);
            assertThat(properties.getName()).isEqualTo("test-mcp-server");
            assertThat(properties.getVersion()).isEqualTo("1.0.0");
            McpServerStreamableHttpProperties streamableHttpProperties = serverContext.getBean(McpServerStreamableHttpProperties.class);
            assertThat(streamableHttpProperties.getMcpEndpoint()).isEqualTo("/mcp");
            assertThat(streamableHttpProperties.getKeepAliveInterval()).isEqualTo(Duration.ofSeconds(1));
            var httpServer = startHttpServer(serverContext, serverPort);
            this.clientApplicationContext.withUserConfiguration(TestMcpClientConfiguration.class).// @formatter:off
            withPropertyValues("spring.ai.mcp.client.streamable-http.connections.server1.url=http://localhost:" + serverPort, // @formatter:on
            "spring.ai.mcp.client.initialized=false").run(clientContext -> {
                McpSyncClient mcpClient = getMcpSyncClient(clientContext);
                assertThat(mcpClient).isNotNull();
                var initResult = mcpClient.initialize();
                assertThat(initResult).isNotNull();
                // TOOLS / SAMPLING / ELICITATION
                // tool list
                assertThat(mcpClient.listTools().tools()).hasSize(3);
                assertThat(mcpClient.listTools().tools()).contains(Tool.builder().name("tool1").description("tool1 description").inputSchema(jsonMapper, """
                    {
                    	"": "http://json-schema.org/draft-07/schema#",
                    	"type": "object",
                    	"properties": {}
                    }
                    """).build());
                // Call a tool that sends progress notifications
                CallToolRequest toolRequest = CallToolRequest.builder().name("tool1").arguments(Map.of()).build();
                CallToolResult response = mcpClient.callTool(toolRequest);
                assertThat(response).isNotNull();
                assertThat(response.isError()).isNull();
                String responseText = ((TextContent) response.content().get(0)).text();
                assertThat(responseText).contains("CALL RESPONSE");
                // TOOL STRUCTURED OUTPUT
                // Call tool with valid structured output
                CallToolResult calculatorToolResponse = mcpClient.callTool(new McpSchema.CallToolRequest("calculator", Map.of("expression", "2 + 3")));
                assertThat(calculatorToolResponse).isNotNull();
                assertThat(calculatorToolResponse.isError()).isFalse();
                assertThat(calculatorToolResponse.structuredContent()).isNotNull();
                assertThat(calculatorToolResponse.structuredContent()).asInstanceOf(map(String.class, Object.class)).containsEntry("result", 5.0).containsEntry("operation", "2 + 3").containsEntry("timestamp", "2024-01-01T10:00:00Z");
                net.javacrumbs.jsonunit.assertj.JsonAssertions.assertThatJson(calculatorToolResponse.structuredContent()).when(Option.IGNORING_ARRAY_ORDER).when(Option.IGNORING_EXTRA_ARRAY_ITEMS).isObject().isEqualTo(net.javacrumbs.jsonunit.assertj.JsonAssertions.json("""
                    {"result":5.0,"operation":"2 + 3","timestamp":"2024-01-01T10:00:00Z"}"""));
                // TOOL FROM MCP TOOL UTILS
                // Call the tool to ensure arguments are passed correctly
                CallToolResult toUpperCaseResponse = mcpClient.callTool(new McpSchema.CallToolRequest("toUpperCase", Map.of("input", "hello world")));
                assertThat(toUpperCaseResponse).isNotNull();
                assertThat(toUpperCaseResponse.isError()).isFalse();
                assertThat(toUpperCaseResponse.content()).hasSize(1).first().isInstanceOf(TextContent.class).extracting("text").isEqualTo("\"HELLO WORLD\"");
                // PROMPT / COMPLETION
                // list prompts
                assertThat(mcpClient.listPrompts()).isNotNull();
                assertThat(mcpClient.listPrompts().prompts()).hasSize(1);
                // get prompt
                GetPromptResult promptResult = mcpClient.getPrompt(new GetPromptRequest("code-completion", Map.of("language", "java")));
                assertThat(promptResult).isNotNull();
                // completion
                CompleteRequest completeRequest = new CompleteRequest(new PromptReference("ref/prompt", "code-completion", "Code completion"), new CompleteRequest.CompleteArgument("language", "py"));
                CompleteResult completeResult = mcpClient.completeCompletion(completeRequest);
                assertThat(completeResult).isNotNull();
                assertThat(completeResult.completion().total()).isEqualTo(10);
                assertThat(completeResult.completion().values()).containsExactly("python", "pytorch", "pyside");
                assertThat(completeResult.meta()).isNull();
                // RESOURCES
                assertThat(mcpClient.listResources()).isNotNull();
                assertThat(mcpClient.listResources().resources()).hasSize(1);
                assertThat(mcpClient.listResources().resources().get(0)).isEqualToComparingFieldByFieldRecursively(Resource.builder().uri("file://resource").name("Test Resource").mimeType("text/plain").description("Test resource description").build());
            });
            stopHttpServer(httpServer);
        });
    }

    // Helper methods to start and stop the HTTP server
    private static DisposableServer startHttpServer(ApplicationContext serverContext, int port) {
        WebFluxStatelessServerTransport mcpStatelessServerTransport = serverContext.getBean(WebFluxStatelessServerTransport.class);
        HttpHandler httpHandler = RouterFunctions.toHttpHandler(mcpStatelessServerTransport.getRouterFunction());
        ReactorHttpHandlerAdapter adapter = new ReactorHttpHandlerAdapter(httpHandler);
        return HttpServer.create().port(port).handle(adapter).bindNow();
    }

    private static void stopHttpServer(DisposableServer server) {
        if (server != null) {
            server.disposeNow();
        }
    }

    // Helper method to get the MCP sync client
    private static McpSyncClient getMcpSyncClient(ApplicationContext clientContext) {
        ObjectProvider<List<McpSyncClient>> mcpClients = clientContext.getBeanProvider(ResolvableType.forClassWithGenerics(List.class, McpSyncClient.class));
        return mcpClients.getIfAvailable().get(0);
    }

    public static class TestMcpServerConfiguration {

        @Bean
        public List<McpStatelessServerFeatures.SyncToolSpecification> myTools() {
            // Tool 1
            McpStatelessServerFeatures.SyncToolSpecification tool1 = McpStatelessServerFeatures.SyncToolSpecification.builder().tool(Tool.builder().name("tool1").description("tool1 description").inputSchema(jsonMapper, """
                {
                	"": "http://json-schema.org/draft-07/schema#",
                	"type": "object",
                	"properties": {}
                }
                """).build()).callHandler((exchange, request) -> new CallToolResult(List.of(new TextContent("CALL RESPONSE")), null)).build();
            // Tool 2
            // Create a tool with output schema
            Map<String, Object> outputSchema = Map.of("type", "object", "properties", Map.of("result", Map.of("type", "number"), "operation", Map.of("type", "string"), "timestamp", Map.of("type", "string")), "required", List.of("result", "operation"));
            Tool calculatorTool = Tool.builder().name("calculator").description("Performs mathematical calculations").outputSchema(outputSchema).build();
            McpStatelessServerFeatures.SyncToolSpecification tool2 = McpStatelessServerFeatures.SyncToolSpecification.builder().tool(calculatorTool).callHandler((exchange, request) -> {
                String expression = (String) request.arguments().getOrDefault("expression", "2 + 3");
                double result = this.evaluateExpression(expression);
                return CallToolResult.builder().structuredContent(Map.of("result", result, "operation", expression, "timestamp", "2024-01-01T10:00:00Z")).build();
            }).build();
            // Tool 3
            // Using a tool with McpToolUtils
            McpStatelessServerFeatures.SyncToolSpecification tool3 = McpToolUtils.toStatelessSyncToolSpecification(FunctionToolCallback.builder("toUpperCase", (ToUpperCaseRequest req, ToolContext context) -> req.input().toUpperCase()).description("Sets the input string to upper case").inputType(ToUpperCaseRequest.class).build(), null);
            return List.of(tool1, tool2, tool3);
        }

        @Bean
        public List<McpStatelessServerFeatures.SyncPromptSpecification> myPrompts() {
            var prompt = new McpSchema.Prompt("code-completion", "Code completion", "this is code review prompt", List.of(new PromptArgument("language", "Language", "string", false)));
            var promptSpecification = new McpStatelessServerFeatures.SyncPromptSpecification(prompt, (exchange, getPromptRequest) -> {
                String languageArgument = (String) getPromptRequest.arguments().get("language");
                if (languageArgument == null) {
                    languageArgument = "java";
                }
                var userMessage = new PromptMessage(Role.USER, new TextContent("Hello " + languageArgument + "! How can I assist you today?"));
                return new GetPromptResult("A personalized greeting message", List.of(userMessage));
            });
            return List.of(promptSpecification);
        }

        @Bean
        public List<McpStatelessServerFeatures.SyncCompletionSpecification> myCompletions() {
            var completion = new McpStatelessServerFeatures.SyncCompletionSpecification(new McpSchema.PromptReference("ref/prompt", "code-completion", "Code completion"), (exchange, request) -> {
                var expectedValues = List.of("python", "pytorch", "pyside");
                return new McpSchema.CompleteResult(new // total
                CompleteResult.CompleteCompletion(// total
                expectedValues, // total
                10, // hasMore
                true));
            });
            return List.of(completion);
        }

        @Bean
        public List<McpStatelessServerFeatures.SyncResourceSpecification> myResources() {
            var systemInfoResource = Resource.builder().uri("file://resource").name("Test Resource").mimeType("text/plain").description("Test resource description").build();
            var resourceSpecification = new McpStatelessServerFeatures.SyncResourceSpecification(systemInfoResource, (exchange, request) -> {
                try {
                    var systemInfo = Map.of("os", System.getProperty("os.name"), "os_version", System.getProperty("os.version"), "java_version", System.getProperty("java.version"));
                    String jsonContent = new ObjectMapper().writeValueAsString(systemInfo);
                    return new McpSchema.ReadResourceResult(List.of(new McpSchema.TextResourceContents(request.uri(), "application/json", jsonContent)));
                } catch (Exception e) {
                    throw new RuntimeException("Failed to generate system info", e);
                }
            });
            return List.of(resourceSpecification);
        }

        private double evaluateExpression(String expression) {
            // Simple expression evaluator for testing
            return switch(expression) {
