    @Test
    void chatMemoryWithTools() {
        ToolCallingManager toolCallingManager = DefaultToolCallingManager.builder().build();
        ChatMemory chatMemory = MessageWindowChatMemory.builder().build();
        String conversationId = UUID.randomUUID().toString();
        ChatOptions chatOptions = ToolCallingChatOptions.builder().toolCallbacks(ToolCallbacks.from(new MathTools())).internalToolExecutionEnabled(false).build();
        Prompt prompt = new Prompt(List.of(new SystemMessage("You are a helpful assistant."), new UserMessage("What is 6 * 8?")), chatOptions);
        chatMemory.add(conversationId, prompt.getInstructions());
        Prompt promptWithMemory = new Prompt(chatMemory.get(conversationId), chatOptions);
        ChatResponse chatResponse = this.chatModel.call(promptWithMemory);
        chatMemory.add(conversationId, chatResponse.getResult().getOutput());
        while (chatResponse.hasToolCalls()) {
            ToolExecutionResult toolExecutionResult = toolCallingManager.executeToolCalls(promptWithMemory, chatResponse);
            chatMemory.add(conversationId, toolExecutionResult.conversationHistory().get(toolExecutionResult.conversationHistory().size() - 1));
            promptWithMemory = new Prompt(chatMemory.get(conversationId), chatOptions);
            chatResponse = this.chatModel.call(promptWithMemory);
            chatMemory.add(conversationId, chatResponse.getResult().getOutput());
        }
        assertThat(chatResponse).isNotNull();
        assertThat(chatResponse.getResult().getOutput().getText()).contains("48");
        UserMessage newUserMessage = new UserMessage("What did I ask you earlier?");
        chatMemory.add(conversationId, newUserMessage);
        ChatResponse newResponse = this.chatModel.call(new Prompt(chatMemory.get(conversationId)));
        assertThat(newResponse).isNotNull();
        assertThat(newResponse.getResult().getOutput().getText()).contains("6").contains("8");
    }

