+				for (JsonNode node : jsonNode) {
+					if (node.isObject() && node.has("data") && node.has("mimeType")) {
+						String mimeType = node.get("mimeType").asText();
+						String data = node.get("data").asText();
+						if (mimeType.startsWith("audio")) {
